push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	bd_list = () =>{
		bd_listurl = 	"http://tingshu.kuwo.cn/v2/api/product/rank/tabList";
		return JSON.parse(java.ajax(bd_listurl)).data; 
		}
		push("🔥榜单🔥", null, 1, 1);
bd_list().map($ =>{			
		push($.name, null, 1, 1);
		push($.shareTitle, null, 1, 1);
   	tabId = $.id;
		list = $.tags;
	   list.map(($,index)=>{	   	     	    
 	    title = $.name;		    
	url =  `http://tingshu.kuwo.cn/v2/api/product/rank/dataList?platform=1&notrace=0&kweexVersion=1.1.5&source=kwplayer_ar_9.1.8.1_tqq.apk&rn=10&id=${$.id}&pn={{page}}&tabId=${tabId}&bksource=kwbook_ar_9.1.8.1_tqq.apk`;			 

	if(list.length > 3&&list.length!=4){
		if(index+1 <= list.length - list.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
				}
				else if(list.length == 4){ push(title, url, 1, 0.4);}
				else{ push(title, url, 1, 0.25);}
  });
 });



